/* Datos locales de demostración; no hay backend, persistencia ni llamadas de red. */
const $ = s => document.querySelector(s), $$ = s => [...document.querySelectorAll(s)];
const contexts={norte:{company:'Norte Construcción',project:'Torre Norte',department:'Instalaciones eléctricas',items:[['risk','triangle-alert','Protección colectiva sin confirmar','Zona de Planta 2 pendiente de evidencia actualizada.','J. Martín','Hoy · 12:30','2 registros','Revisar incidencia'],['amber','package-search','Pedido de cable con recepción incompleta','Falta albarán para cerrar la entrega asociada.','Oficina técnica','Hoy · 16:00','1 registro','Ver entrega'],['info','list-checks','Checklist de seguridad a falta de 2 puntos','El cierre depende de confirmar la zona de Planta 2.','Marta Sáez','Hoy · 13:30','4 registros','Abrir checklist']]},atlas:{company:'Atlas Servicios',project:'Centro Logístico Sur',department:'Logística',items:[['amber','package-search','Recepción de material por validar','La entrega necesita albarán y fotografía.','Lucía Campos','Hoy · 15:00','1 registro','Ver entrega'],['info','clipboard-list','Inventario de zona B pendiente','Hay diferencia entre conteo y entrada registrada.','Almacén','Mañana · 09:00','3 registros','Abrir inventario']]}};
const incidents=[{id:'INC-248',tone:'risk',status:'critical',label:'Crítica',title:'Protección colectiva incompleta',owner:'J. Martín',ownerKey:'martin',due:'Hoy · 12:30',evidence:'2',summary:'Falta una foto actualizada del perímetro de Planta 2. La zona permanece señalizada hasta verificar la corrección.',next:'Solicitar evidencia y confirmar cierre.'},{id:'INC-241',tone:'amber',status:'review',label:'Revisión',title:'Pedido de cable sin albarán',owner:'Oficina técnica',ownerKey:'office',due:'Hoy · 16:00',evidence:'1',summary:'La recepción parcial está registrada; falta el documento de entrega para completar la trazabilidad.',next:'Validar albarán con el proveedor.'},{id:'INC-233',tone:'info',status:'open',label:'Abierta',title:'Señalización temporal pendiente',owner:'J. Martín',ownerKey:'martin',due:'Mañana · 09:00',evidence:'4',summary:'El checklist detectó señalización incompleta junto al acceso secundario.',next:'Completar señalización y adjuntar foto.'}];let current=incidents[0];
function icons(){window.lucide?.createIcons({'attrs':{'stroke-width':1.8}})}function view(id){$$('.view').forEach(x=>x.classList.toggle('active',x.id===id));$$('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===id));document.body.classList.toggle('chat-open',id==='chat');icons()}function attention(data){$('#attention').innerHTML=data.items.map(x=>`<article class="attention-item" style="--tone:var(--${x[0]});--toneS:var(--${x[0]}S)"><i data-lucide="${x[1]}"></i><div><h2>${x[2]}</h2><p>${x[3]}</p></div><span>Responsable<b>${x[4]}</b></span><span>Vencimiento<b>${x[5]}</b></span><span>Evidencia<b>${x[6]}</b></span><button class="button secondary" data-view="incidents"><i data-lucide="arrow-right"></i>${x[7]}</button></article>`).join('');icons();$$('#attention [data-view]').forEach(x=>x.addEventListener('click',()=>view('incidents')))}function scope(){let d=contexts[$('#company').value];$('#project').value=$('#company').value;$('#department').value=d.department;$('#scopeNote').innerHTML=`<i data-lucide="shield-check"></i>Datos simulados: ${d.company} · ${d.project} · ${d.department}.`;attention(d);icons()}function detail(x){$('#detail').innerHTML=`<span class="severity ${x.tone}">${x.id} · ${x.label}</span><h2>${x.title}</h2><p>${x.summary}</p><dl><dt>Responsable</dt><dd>${x.owner}</dd><dt>Vence</dt><dd>${x.due}</dd><dt>Evidencia</dt><dd>${x.evidence} registros simulados</dd><dt>Siguiente acción</dt><dd>${x.next}</dd></dl><button class="button violet"><i data-lucide="paperclip"></i>Ver evidencia</button>`;icons()}function rows(){let s=$('#status').value,o=$('#owner').value,r=incidents.filter(x=>(s==='all'||x.status===s)&&(o==='all'||x.ownerKey===o));if(!r.includes(current))current=r[0]||incidents[0];$('#rows').innerHTML=r.length?r.map(x=>`<tr data-id="${x.id}" class="${x.id===current.id?'selected':''}"><td><span class="severity ${x.tone}">${x.label}</span></td><td><b>${x.title}</b><br><small>${x.id}</small></td><td>${x.owner}</td><td>${x.due}</td><td>${x.evidence} registros</td></tr>`).join(''):'<tr><td colspan="5">No hay incidencias para estos filtros simulados.</td></tr>';detail(current);$$('[data-id]').forEach(x=>x.addEventListener('click',()=>{current=incidents.find(y=>y.id===x.dataset.id);rows()}))}function state(type){let out={loading:'<div class="skeleton" aria-label="Cargando datos simulados"><i></i><i></i><i></i></div>',empty:'<article class="demo-state"><h2>No hay informes pendientes</h2><p>El alcance simulado no tiene informes para revisar. Puedes cambiar el contexto o registrar una incidencia si cuentas con evidencia.</p><button class="button secondary">Registrar incidencia</button></article>',error:'<article class="demo-state"><h2>No se pudo actualizar el panorama</h2><p>La última lectura verificada se conserva. Vuelve a intentarlo cuando la fuente esté disponible; no se ha perdido ni alterado ningún dato.</p><button class="button secondary">Reintentar</button></article>'};$('#state').hidden=false;$('#state').innerHTML=out[type]}function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2500)}
$$('[data-view]').forEach(x=>x.addEventListener('click',()=>view(x.dataset.view)));$('#company').addEventListener('change',scope);$('#project').addEventListener('change',()=>{$('#company').value=$('#project').value;scope()});$('#department').addEventListener('change',scope);['status','owner'].forEach(x=>$('#'+x).addEventListener('change',rows));$('#clear').addEventListener('click',()=>{$('#status').value='all';$('#owner').value='all';rows()});$$('[data-state]').forEach(x=>x.addEventListener('click',()=>state(x.dataset.state)));function theme(){document.body.classList.toggle('light');toast(document.body.classList.contains('light')?'Tema claro activado.':'Tema oscuro activado.')}$('#theme').addEventListener('click',theme);$('#theme2').addEventListener('click',theme);$('#scan').addEventListener('click',()=>toast('Escanear es una acción visual simulada; no abre cámara ni procesa datos.'));attention(contexts.norte);rows();icons();
